style.css:
/* Sakura Midnight — Global Anime Theme */
/* i really want this to be global */

/* change these colors to customize the theme */
:root {
  --my-bg: #100d19;
  --my-surface: #1b1528;
  --my-surface-2: #251c35;
  --my-pink: #ff8fcf;
  --my-purple: #b69aff;
  --my-text: #eee8f8;
  --my-muted: #aaa0bd;
}

/* dark backgrounds and text */
html,
body {
  background-color: var(--my-bg) !important;
  color: var(--my-text) !important;
  color-scheme: dark;
}

/* links */
a {
  color: var(--my-pink) !important;
  transition: color 0.2s ease, text-shadow 0.2s ease !important;
}

a:hover {
  color: var(--my-purple) !important;
  text-shadow: 0 0 10px var(--my-purple) !important;
}

/* selection */
::selection {
  background: var(--my-purple) !important;
  color: #100d19 !important;
}

/* form controls */
input,
textarea,
select {
  background: var(--my-surface) !important;
  color: var(--my-text) !important;
  border: 1px solid #443354 !important;
  border-radius: 10px !important;
}

/* buttons */
button {
  border-radius: 9px !important;
  transition: filter 0.2s ease, transform 0.2s ease !important;
}

button:hover {
  filter: brightness(1.2) !important;
}

/* images */
img {
  border-radius: 8px;
}

/* scrollbars */
::-webkit-scrollbar {
  width: 9px;
  height: 9px;
}

::-webkit-scrollbar-track {
  background: var(--my-bg);
}

::-webkit-scrollbar-thumb {
  background: #59416f;
  border-radius: 20px;
}

::-webkit-scrollbar-thumb:hover {
  background: var(--my-pink);
}

/* smooth transitions */
a,
button,
input,
textarea,
select {
  transition-duration: 0.2s !important;
}
